<script setup>
import {computed,reactive,ref,watch,onUnmounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {account,passwordValid,fileError} from '../account'
import {session,openModal,logout} from '../session'
import {path} from '../data'
import {locale,languages,applyLocale,t} from '../i18n'
import QRCode from 'qrcode'
import Survey from './Survey.vue'
import Icon from '../components/Icon.vue'
const locationOrigin=location.origin
const referralQr=ref('')
watch(locale,async()=>{referralQr.value=await QRCode.toDataURL(locationOrigin+'/newtrend'+path('/register')+'?ref=DEMO10001',{width:160,margin:1})},{immediate:true})
const route=useRoute(),router=useRouter(),page=computed(()=>route.params.account),id=computed(()=>route.params.id),step=ref(1),sent=ref(false),count=ref(0),error=ref(''),success=ref(''),files=reactive({}),filter=ref('全部'),query=ref(''),editing=ref(false),draftName=ref(account.name)
const form=reactive({old:'',password:'',confirm:'',email:'',phone:'',prefix:'+1',code:'',fullName:'',idType:'',idNumber:'',country:'',referral:'',relationship:'',uid:'',proofType:'BANK_STATEMENT',note:''});let countdown
const isFund=computed(()=>page.value==='fund-password'),isPassword=computed(()=>isFund.value||page.value==='change-password'),isBinding=computed(()=>['bind-email','bind-phone'].includes(page.value)),isEmail=computed(()=>page.value==='bind-email')
const title=computed(()=>{const p=page.value;return p==='change-password'?t('profile.changePassword.title'):p==='fund-password'?t('profile.fundPasswordPage.'+(account.fundPasswordSet?'changeTitle':'setTitle')):p==='bind-email'?t('profile.bindEmailPage.'+(account.email?'titleChange':'titleBind')):p==='bind-phone'?t('profile.bindPhonePage.'+(account.phone?'titleChange':'titleBind')):p==='2fa'?t('twoFactor.'+(account.twoFactor?'2faStatus':'bind2fa')):p==='kyc'?t(id.value==='basic'?'kyc.kycTitle':id.value==='advanced'?'kyc.advanced.pageTitle':'kyc.center.title'):p==='referrals'?t('referral.page.title'):p==='joint-account'?t('jointAccount.page.title'):p==='promotions'?t('promotion.list.title'):p==='devices'?t('devices.title'):p==='help-center'?t('profile.helpCenterPage.title'):p==='survey'?t('survey.entry.title'):t('profile.pageTitle')})
const subtitle=computed(()=>{const p=page.value;return p==='change-password'?t('profile.changePassword.subtitle'):p==='fund-password'?t('profile.fundPasswordPage.'+(account.fundPasswordSet?'changeSubtitle':'setSubtitle')):p==='bind-email'?t('profile.bindEmailPage.subtitleChange'):p==='bind-phone'?t('profile.bindPhonePage.subtitleBind'):p==='2fa'?t('twoFactor.bind2faDesc'):p==='kyc'?t(id.value==='basic'?'kyc.kycDesc':id.value==='advanced'?'kyc.advanced.pageDesc':'kyc.center.subtitle'):p==='referrals'?t('referral.page.description'):p==='devices'?t('devices.subtitle'):p==='joint-account'?t('jointAccount.page.description'):p==='promotions'?t('promotion.list.description'):p==='help-center'?t('profile.helpCenterPage.subtitle'):''})
const validPassword=computed(()=>isFund.value?/^\d{6}$/.test(form.password):passwordValid(form.password)),validContact=computed(()=>isEmail.value?/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email):/^\d{6,15}$/.test(form.phone))
const security=computed(()=>account.fundPasswordSet&&account.twoFactor?'高':account.fundPasswordSet||account.twoFactor?'中':'低')
function setLanguage(l){applyLocale(l);router.replace({path:route.path.replace(/^\/[^/]+/,'/'+l),query:route.query,hash:route.hash})}
function reset(){step.value=1;sent.value=false;count.value=0;error.value='';success.value='';clearInterval(countdown);Object.keys(files).forEach(k=>delete files[k]);for(const k of Object.keys(form))form[k]=k==='prefix'?'+1':k==='proofType'?'BANK_STATEMENT':''}
watch(()=>page.value+'|'+id.value,reset);onUnmounted(()=>clearInterval(countdown))
function passwordSubmit(){error.value='';if(!validPassword.value){error.value=isFund.value?'僅可包含 6 位數字':'請檢查密碼規則';return}if(form.password!==form.confirm){error.value='兩次輸入的密碼不一致';return}if(form.old&&form.old===form.password){error.value='新密碼不能與舊密碼相同';return}if(isFund.value)account.fundPasswordSet=true;form.old=form.password=form.confirm='';success.value=isFund.value?'資金密碼已設置':'登入密碼已修改'}
function sendCode(){if(!validContact.value)return;if(isEmail.value&&form.email===account.email){error.value='新郵箱不能與當前郵箱相同';return}sent.value=true;count.value=60;error.value='';clearInterval(countdown);countdown=setInterval(()=>{if(--count.value<=0)clearInterval(countdown)},1000)}
function bind(){if(form.code!=='123456'){error.value='驗證碼無效或已過期';return}if(isEmail.value)account.email=form.email;else account.phone=form.prefix+' '+form.phone;success.value=isEmail.value?'郵箱修改成功':'手機號碼綁定成功';form.code='';sent.value=false}
function toggle2fa(){if(form.code!=='123456'){error.value='驗證碼無效或已過期';return}account.twoFactor=!account.twoFactor;success.value=account.twoFactor?'綁定成功':'解除綁定成功';form.code='';error.value=''}
function selectFile(key,e){const file=e.target.files?.[0];error.value=fileError(file,20);if(!error.value)files[key]=file.name;else delete files[key]}
function nextKyc(){if(!form.fullName.trim()||!form.idType||!form.idNumber.trim()||!form.country){error.value='請填寫所有必填項';return}error.value='';step.value=2}
function submitKyc(){const required=id.value==='advanced'?['handheld','proof']:['front','back','selfie'];if(required.some(k=>!files[k])){error.value='請上傳所有必需證件';return}if(id.value==='advanced')account.advanced='pending';else account.kyc='pending';success.value='提交成功，您的申請正在審核中';error.value=''}
function copy(value){navigator.clipboard.writeText(value).then(()=>success.value='已複製').catch(()=>error.value='複製失敗')}
function rename(d){openModal('account-edit','重新命名裝置',{value:d.name,onSave:v=>d.name=v})}
function revoke(d){openModal('account-confirm','撤銷裝置',{description:d.current?'這是你目前使用的裝置，撤銷後將立即登出。':'該裝置將被登出，其所有存取憑證將立即失效。',onConfirm:()=>{account.devices=account.devices.filter(x=>x.id!==d.id);if(d.current){logout();router.push(path('/login'))}}})}
function saveName(){if(!draftName.value.trim()){error.value='請輸入用戶名';return}account.name=draftName.value.trim();editing.value=false;success.value='暱稱已更新'}
function submitReferral(){if(account.referrer){error.value='你的帳號已綁定邀請人。';return}if(!form.referral.trim()||form.referral==='DEMO10001'){error.value='邀請碼無效,請確認後重試。';return}account.referrer=form.referral;success.value='已綁定邀請碼'}
function applyJoint(){if(account.kyc!=='approved'){step.value=2;return}step.value=3}
function submitJoint(){if(!form.relationship||!/^\d{5,12}$/.test(form.uid)||form.uid==='10000001'||!files.relationship){error.value='請填寫所有欄位並上傳必要文件。';return}account.joint={uid:form.uid,relationship:form.relationship,status:'pending_consent'};step.value=1;success.value='申請已提交'}
const faqIds=['account1','account2','trade1','trade2','deposit1','deposit2','security1','security2'];const faqs=computed(()=>faqIds.filter(k=>(filter.value==='全部'||k.startsWith(filter.value))&&t('profile.helpCenterPage.faq.'+k).toLowerCase().includes(query.value.toLowerCase())))
</script>
<template><div :class="[page==='profile'?'account-center':'account-page','account-'+page]"><RouterLink v-if="page!=='profile'" :to="path('/profile')" class="muted back-link">{{ $tr("← 返回") }}</RouterLink><header class="account-heading" :class="{'account-banner':['referrals','promotions'].includes(page)}"><small v-if="page==='referrals'" class="page-kicker">{{t('referral.page.subtitle')}}</small><h1>{{title}}</h1><p v-if="subtitle" class="account-subtitle">{{subtitle}}</p><p v-if="page==='referrals'" class="tag-chip section-gap">{{t('referral.page.qualificationHint',{amount:'2,000'})}}</p></header>
<template v-if="page==='profile'"><section class="profile-overview"><div class="profile-identity"><Icon name="user"/><div><h2>{{ $tr(account.name) }} <button :aria-label="$tr(&quot;修改用戶名&quot;)" @click="openModal('account-edit','修改用戶名',{value:account.name,onSave:v=>account.name=v})"><Icon name="pencil"/></button></h2><p class="muted">{{ $tr("UID 10000001 ") }}<button :aria-label="$tr(&quot;複製 UID&quot;)" @click="copy('10000001')"><Icon name="copy"/></button></p></div></div><div class="profile-metrics"><RouterLink :to="path('/kyc')"><small>{{ $tr("實名認證") }}</small><strong>{{ $tr(account.kyc==='none'?'未認證':account.kyc==='pending'?'審核中':'已認證') }}</strong><span class="green-link">{{ $tr("立即認證") }}</span></RouterLink><RouterLink :to="path('/fund-password')"><small>{{ $tr("安全等級") }}</small><strong>{{ $tr(security) }}</strong><div class="progress"><span :style="{width:security==='高'?'100%':security==='中'?'65%':'35%'}"></span></div><small>{{ t('profile.securityTodo',{items:[!account.fundPasswordSet?t('profile.fundPassword'):'',!account.twoFactor?t('profile.twoFactor'):''].filter(Boolean).join(' · ')}) }}</small></RouterLink><button @click="openModal('vip','VIP 等級')"><small>{{ $tr("VIP 等級") }}</small><strong>{{ $tr("VIP 0") }}</strong><div class="progress"><span style="width:0"></span></div><small>{{ t('profile.vip.amountToNext',{tier:1,amount:'100,000'}) }}</small></button><div><small>{{ $tr("信用分") }}</small><strong>100 <span class="positive">{{ $tr("信用良好") }}</span></strong><div class="progress"><span style="width:100%"></span></div><small>{{ t('profile.creditScoreHint',{max:100}) }}</small></div></div></section><div class="profile-columns"><section class="profile-box"><header><h2>{{ $tr("個人設定") }}</h2><small>{{ $tr("只影響你自己的帳戶") }}</small></header><div v-for="[group,items] in [['帳戶',[['實名認證','/kyc',account.kyc==='none'?'未認證':'審核中','shield'],['郵箱','/bind-email',account.email||'未綁定','mail'],['手機號碼','/bind-phone',account.phone||'未綁定','wallet']]],['安全',[['登入密碼','/change-password','已設置','shield'],['資金密碼','/fund-password',account.fundPasswordSet?'已設置':'未設置','wallet'],['雙重認證','/2fa',account.twoFactor?'已開啟':'未開啟','shield'],['裝置管理','/devices','','layers']]]]" :key="group" class="profile-group"><small>{{ $tr(group) }}</small><RouterLink v-for="item in items" :key="item[0]" :to="path(item[1])"><Icon :name="item[3]"/><span>{{ $tr(item[0]) }}</span><small>{{ $tr(item[2]) }}</small><Icon name="chevron-right"/></RouterLink></div><div class="profile-group"><small>{{ $tr("偏好") }}</small><label>{{ $tr("語言") }}<select :value="locale" @change="setLanguage($event.target.value)"><option v-for="[code,name] in languages" :value="code">{{ $tr(name) }}</option></select></label><label>{{ $tr("字體大小") }}<select v-model="account.fontScale"><option value="standard">{{ $tr("標準") }}</option><option value="large">{{ $tr("大") }}</option><option value="xlarge">{{ $tr("特大") }}</option></select></label></div></section><div><section class="profile-box"><header><h2>{{ $tr("我的業務") }}</h2><small>{{ $tr("你在平台上參與的功能") }}</small></header><div class="profile-group"><button @click="openModal('vip','VIP 等級')"><Icon name="trophy"/><span>{{ $tr("VIP 等級") }}</span><small>{{ $tr("VIP 0") }}</small><Icon name="chevron-right"/></button><RouterLink v-for="[name,to,icon] in [['聯名帳戶','/joint-account','users'],['邀請好友','/referrals','users'],['我的活動','/promotions/tasks','trophy'],['問卷調查','/survey/019e9f01-47a3-711f-9052-e7187b9f9407','layers']]" :key="to" :to="path(to)"><Icon :name="icon"/><span>{{ $tr(name) }}</span><Icon name="chevron-right"/></RouterLink></div></section><section class="profile-box"><header><h2>{{ $tr("支援") }}</h2></header><div class="profile-group"><RouterLink :to="path('/help-center')">{{ $tr("幫助中心 ") }}<Icon name="chevron-right"/></RouterLink><button @click="openModal('support','線上客服')">{{ $tr("聯絡客服 ") }}<Icon name="chevron-right"/></button><RouterLink :to="path('/about')">{{ $tr("關於我們 ") }}<Icon name="chevron-right"/></RouterLink></div></section><button class="secondary-button wide-button" @click="openModal('account-confirm','確認登出',{description:'登出後需要重新登入才能繼續操作。確定要登出嗎？',onConfirm:()=>{logout();router.push(path('/login'))}})">{{ $tr("登出") }}</button></div></div></template>
<form v-else-if="isPassword" class="account-form" @submit.prevent="passwordSubmit"><label v-if="!isFund||account.fundPasswordSet">{{ $tr(isFund?'舊資金密碼':'舊密碼') }}<input v-model="form.old" type="password" :placeholder="$tr(isFund?'請輸入舊資金密碼':'請輸入舊密碼')" autocomplete="off" required/></label><label>{{ $tr(isFund?'資金密碼':'新密碼') }}<input v-model="form.password" type="password" :placeholder="$tr(isFund?'請輸入 6 位數字資金密碼':'請輸入新密碼')" autocomplete="new-password" :maxlength="isFund?6:30"/></label><ul class="password-rules"><template v-if="isFund"><li :class="{positive:validPassword}">{{ $tr("僅可包含 6 位數字") }}</li></template><template v-else><li :class="{positive:form.password.length>=8&&form.password.length<=30}">{{ $tr("8–30 位字元") }}</li><li :class="{positive:/[a-z]/i.test(form.password)}">{{ $tr("需含英文字母（區分大小寫）") }}</li><li :class="{positive:/[^a-z]/i.test(form.password)}">{{ $tr("不能僅由英文字母組成") }}</li><li :class="{positive:/^[A-Za-z0-9@#$*.]+$/.test(form.password)}">{{ $tr("特殊字元僅支援 @ # $ * .") }}</li></template></ul><label>{{ $tr("確認密碼") }}<input v-model="form.confirm" type="password" :placeholder="$tr(isFund?'請再次輸入資金密碼':'請再次輸入新密碼')" autocomplete="new-password"/></label><button class="primary-button wide-button" :disabled="!validPassword||!form.confirm">{{ $tr("確認") }}</button><RouterLink class="muted center" :to="path('/forgot-password')">{{ $tr("忘記密碼?") }}</RouterLink></form>
<form v-else-if="isBinding" class="account-form binding-form" @submit.prevent="sent?bind():sendCode()"><label v-if="isEmail&&account.email">{{ $tr("當前郵箱") }}<input :value="account.email" disabled/></label><label>{{ $tr(isEmail?'郵箱':'手機號碼') }}<input v-if="isEmail" v-model="form.email" type="email" :placeholder="$tr(&quot;請輸入您的郵箱&quot;)" :disabled="sent"/><div v-else class="phone-input"><select v-model="form.prefix" :aria-label="$tr(&quot;國家區碼&quot;)" :disabled="sent"><option v-for="p in ['+1','+44','+49','+33','+81','+82','+86','+852','+886','+63']" :value="p">{{ $tr(p) }}</option></select><input v-model="form.phone" inputmode="tel" :placeholder="$tr(&quot;請輸入手機號碼&quot;)" :disabled="sent"/></div></label><template v-if="sent"><label>{{ $tr("驗證碼") }}<input v-model="form.code" inputmode="numeric" maxlength="6" :placeholder="$tr(&quot;請輸入 6 位數驗證碼&quot;)" autocomplete="one-time-code"/></label><p class="notice">{{ $tr("本地演示驗證碼：123456") }}</p><button type="button" class="green-link" :disabled="count>0" @click="sendCode">{{ $tr(count>0?t('profile.bindEmailPage.resendInSeconds',{count}):t('profile.bindEmailPage.resend')) }}</button><button type="button" class="muted" @click="sent=false">{{ $tr("修改") }}</button></template><button class="primary-button wide-button" :disabled="!validContact||(sent&&form.code.length!==6)">{{ t('profile.'+(isEmail?'bindEmailPage':'bindPhonePage')+'.'+(sent?((isEmail?account.email:account.phone)?'submitChange':'submitBind'):'sendCode')) }}</button></form>
<form v-else-if="page==='2fa'" class="account-form" @submit.prevent="toggle2fa"><template v-if="!account.twoFactor"><section><h3>{{ $tr(t('twoFactor.step1')) }}: {{ $tr(t('twoFactor.downloadApp')) }}</h3><div class="two-cols section-gap"><a class="secondary-button" href="https://apps.apple.com/app/google-authenticator/id388497605" target="_blank" rel="noopener"><img class="auth-qr" src="/newtrend/assets/auth-ios.svg" alt="iOS Google Authenticator"/>{{ $tr("iOS ↗") }}</a><a class="secondary-button" href="https://play.google.com/store/apps/details?id=com.google.android.apps.authenticator2" target="_blank" rel="noopener"><img class="auth-qr" src="/newtrend/assets/auth-android.svg" alt="Android Google Authenticator"/>{{ $tr("Android ↗") }}</a></div></section><section><h3>{{ $tr(t('twoFactor.step2')) }}: {{ $tr(t('twoFactor.scanOrCopy')) }}</h3><p class="notice section-gap">{{ $tr("本地演示密鑰，不可用於真實帳戶。") }}</p><img class="auth-qr" src="/newtrend/assets/demo-auth.svg" alt="Local demo QR code"/><div class="demo-key">{{ $tr("DEMO-LOCAL-ONLY-000000 ") }}<button type="button" :aria-label="$tr(&quot;複製&quot;)" @click="copy('DEMO-LOCAL-ONLY-000000')"><Icon name="layers"/></button></div><p class="muted">{{ $tr("無法掃描？可手動輸入密鑰") }}</p></section></template><template v-else><div class="card"><Icon name="shield" green/><h3>{{ $tr("已開啟") }}</h3><p class="muted section-gap">{{ $tr("您的賬戶已啟用雙重認證") }}</p></div></template><label>{{ $tr(account.twoFactor?t('twoFactor.enterOtpToUnbind'):t('twoFactor.enterOtp')) }}<input v-model="form.code" inputmode="numeric" maxlength="6" :placeholder="$tr(&quot;請輸入6位數字&quot;)"/></label><p class="notice">{{ $tr("本地演示驗證碼：123456") }}</p><button class="primary-button wide-button" :disabled="form.code.length!==6">{{ t('twoFactor.'+(account.twoFactor?'confirmUnbind':'confirm')) }}</button></form>
<template v-else-if="page==='devices'"><div v-if="!account.devices.length" class="empty">{{ $tr("尚無登入裝置紀錄。") }}</div><article v-for="d in account.devices" :key="d.id" class="card account-device"><div class="summary-line"><div><h3>{{ $tr(d.name) }}</h3><p class="muted">{{ $tr(d.current?'目前裝置':'') }} {{ $tr(d.trusted?'已信任':'') }}</p><p class="mini-label">{{ $tr("Local browser · 2026-11-24") }}</p></div><Icon name="layers"/></div><div class="device-actions"><button @click="rename(d)">{{ $tr("重新命名") }}</button><button :disabled="d.trusted" @click="d.trusted=true">{{ $tr("信任") }}</button><button class="negative" @click="revoke(d)">{{ $tr("撤銷") }}</button></div></article></template>
<template v-else-if="page==='kyc'"><div v-if="!id" class="two-cols section-gap"><RouterLink class="card" :to="path('/kyc/basic')"><div class="summary-line"><span class="tag-chip">{{ $tr("Level 1") }}</span><span>{{ $tr(account.kyc==='none'?'未認證':account.kyc==='pending'?'審核中':'已認證') }}</span></div><h2 class="section-gap">{{ $tr("基礎認證") }}</h2><p class="muted section-gap">{{ $tr("提交身份信息與證件照片，完成實名認證") }}</p><span class="green-link section-gap">{{ $tr("前往認證 →") }}</span></RouterLink><div class="card"><span class="tag-chip">{{ $tr("Level 2") }}</span><h2 class="section-gap">{{ $tr("高級驗證") }}</h2><p class="muted section-gap">{{ $tr("提供更多資料，解鎖更高交易額度與權限") }}</p><RouterLink v-if="account.kyc==='approved'" class="green-link section-gap" :to="path('/kyc/advanced')">{{ $tr("前往驗證 →") }}</RouterLink><p v-else class="mini-label section-gap">{{ $tr("請先完成基礎認證（Level 1）後解鎖") }}</p></div></div><div v-else-if="(id==='basic'?account.kyc:account.advanced)==='pending'" class="card section-gap"><h2>{{ $tr("審核中") }}</h2><p class="muted section-gap">{{ $tr(t('kyc.pendingTip')) }}</p><p class="mini-label section-gap">{{ $tr(t('kyc.pendingHint')) }}</p></div><div v-else-if="id==='advanced'&&account.kyc!=='approved'" class="notice section-gap">{{ $tr(t('kyc.advanced.lockedHint')) }}</div><form v-else class="account-form" @submit.prevent="step===1&&id==='basic'?nextKyc():submitKyc()"><div v-if="id==='basic'" class="kyc-steps"><span :class="{active:step===1}">{{ $tr("1　個人信息") }}</span><span :class="{active:step===2}">{{ $tr("2　證件上傳") }}</span></div><template v-if="step===1&&id==='basic'"><label>{{ $tr("真實姓名") }}<input v-model="form.fullName" :placeholder="$tr(&quot;請輸入真實姓名&quot;)"/></label><label>{{ $tr("證件類型") }}<select v-model="form.idType"><option disabled value="">{{ $tr("請選擇證件類型") }}</option><option :value="&quot;身份證&quot;">{{ $tr("身份證") }}</option><option :value="&quot;護照&quot;">{{ $tr("護照") }}</option><option :value="&quot;駕照&quot;">{{ $tr("駕照") }}</option></select></label><label>{{ $tr("證件號碼") }}<input v-model="form.idNumber" :placeholder="$tr(&quot;請輸入證件號碼&quot;)"/></label><label>{{ $tr("國家/地區") }}<select v-model="form.country"><option disabled value="">{{ $tr("請輸入國家/地區") }}</option><option v-for="c in ['United States','United Kingdom','Taiwan','Hong Kong','China','Japan','Korea','Germany','France','Philippines','Singapore']" :value="c">{{ $tr(c) }}</option></select></label><button class="primary-button wide-button">{{ $tr("下一步") }}</button></template><template v-else><p class="notice">{{ $tr("僅使用虛構資料與演示圖片。檔案不會上傳。") }}</p><label v-for="[key,label] in id==='basic'?[['front','身份證正面'],['back','身份證反面'],['selfie','手持自拍照']]:[['handheld','手持證件照'],['proof','資產證明']]" :key="key">{{ $tr(label) }}<span class="upload-box"><Icon name="layers"/>{{ $tr(files[key]||t('kyc.clickToUpload')) }}<input type="file" accept="image/png,image/jpeg,application/pdf" :aria-label="$tr(label)" @change="selectFile(key,$event)"/></span></label><button v-if="id==='basic'" type="button" class="secondary-button" @click="step=1">{{ $tr("返回") }}</button><button class="primary-button wide-button">{{ $tr("提交認證") }}</button></template></form></template>
<template v-else-if="page==='referrals'"><form class="card referral-bind section-gap" @submit.prevent="submitReferral"><h2><Icon name="users" green/>{{t('referral.bind.title')}}</h2><p class="muted">{{t('referral.bind.description')}}</p><div class="referral-bind-input"><input v-model="form.referral" :placeholder="t('referral.bind.placeholder')" :aria-label="t('referral.bind.title')" :disabled="!!account.referrer"/><button class="primary-button" :disabled="!!account.referrer||!form.referral.trim()">{{account.referrer?t('referral.bind.success'):t('referral.bind.submit')}}</button></div></form><div class="referral-stats section-gap"><section class="card referral-code"><h2>{{t('referral.code.title')}}</h2><div class="summary-line"><strong>DEMO10001</strong><button class="secondary-button" @click="copy('DEMO10001')">{{t('referral.code.copy')}}</button></div></section><section v-for="key in ['totalInvited','qualifiedCount','rewardedCount','totalAccumulated']" :key="key" class="card"><small>{{t('referral.stats.'+key)}}</small><p><strong>0</strong><small v-if="key==='totalAccumulated'"> USDT</small></p></section></div><section class="card referral-share section-gap"><h2>{{t('referral.shareLink.title')}}</h2><p class="muted">{{t('referral.shareLink.description')}}</p><div class="referral-share-content"><img v-if="referralQr" :src="referralQr" :alt="t('referral.shareLink.qrAlt')"/><div><div class="demo-key">{{locationOrigin+'/newtrend'+path('/register')+'?ref=DEMO10001'}}</div><div class="summary-line"><small class="muted">{{t('referral.shareLink.scanHint')}}</small><button class="secondary-button" @click="copy(locationOrigin+'/newtrend'+path('/register')+'?ref=DEMO10001')">{{t('referral.shareLink.copy')}}</button></div></div></div></section><section class="card referral-invitees section-gap"><h2>{{t('referral.invitees.title')}}</h2><div class="empty"><Icon name="users"/><h3>{{t('referral.empty.title')}}</h3><p>{{t('referral.empty.description')}}</p></div></section></template>
<template v-else-if="page==='joint-account'"><template v-if="step===2"><div class="card section-gap"><h2>{{ $tr(t('jointAccount.apply.kycRequiredTitle')) }}</h2><p class="muted section-gap">{{ $tr(t('jointAccount.apply.kycRequiredDesc')) }}</p><div class="device-actions"><button class="secondary-button" @click="step=1">{{ $tr("取消") }}</button><RouterLink class="primary-button" :to="path('/kyc')">{{ $tr("前往認證") }}</RouterLink></div></div></template><form v-else-if="step===3" class="account-form" @submit.prevent="submitJoint"><label>{{ $tr("與對方的關係") }}<select v-model="form.relationship"><option disabled value="">{{ $tr("請選擇") }}</option><option v-for="r in ['配偶','家人','合夥人','代理人']" :value="r">{{ $tr(r) }}</option></select></label><label>{{ $tr("對方的 UID") }}<input v-model="form.uid" :placeholder="$tr(&quot;例如 100023&quot;)" inputmode="numeric"/></label><label>{{ $tr("關係證明") }}<input type="file" accept="image/jpeg,image/png,application/pdf" @change="selectFile('relationship',$event)"/></label><p class="notice">{{ $tr("本地申請不建立真實聯名帳戶。") }}</p><button class="primary-button">{{ $tr("提交申請") }}</button><button type="button" class="secondary-button" @click="step=1">{{ $tr("取消") }}</button></form><template v-else><div class="joint-holder card section-gap"><small>{{ $tr("帳戶持有人") }}</small><div class="two-cols section-gap"><div><h2>{{ $tr(account.name) }}</h2><p class="mini-label">{{ $tr("主申請人 · 您") }}</p></div><div><h2 class="muted">{{ $tr(account.joint?account.joint.uid:'待加入') }}</h2><p class="mini-label">{{ $tr("成員") }}</p></div></div></div><ul class="joint-points"><li v-for="k in ['ownership','switch','exit']">{{ $tr(t('jointAccount.intro.points.'+k)) }}</li></ul><p v-if="account.joint" class="notice">{{ $tr(t('jointAccount.application.title.pending_consent')) }}</p><button v-else class="primary-button" @click="applyJoint">{{ $tr("申請") }}</button><p class="mini-label section-gap">{{ $tr(t('jointAccount.intro.prepare')) }}<br/>{{ $tr(t('jointAccount.intro.kycOnly')) }}</p><details v-for="k in ['memberCan','memberSteps','dissolve']" :key="k" class="account-faq"><summary>{{ $tr(t('jointAccount.faq.'+k+'.q')) }}</summary><p>{{ $tr(t('jointAccount.faq.'+k+'.a')) }}</p></details></template></template>
<template v-else-if="page==='promotions'"><div class="empty"><Icon name="trophy"/><h2>{{ $tr(t('promotion.empty.title')) }}</h2><p>{{ $tr(t('promotion.empty.description')) }}</p></div></template>
<template v-else-if="page==='survey'"><Survey/></template>
<template v-else-if="page==='help-center'"><input v-model="query" :placeholder="$tr(t('profile.helpCenterPage.searchPlaceholder'))" :aria-label="$tr(t('profile.helpCenterPage.searchPlaceholder'))" class="wide-button section-gap"/><div class="filter-row"><button v-for="[key,label] in [['全部','全部'],['account','帳戶相關'],['trade','交易問題'],['deposit','充提問題'],['security','安全設定']]" :class="{active:filter===key}" @click="filter=key">{{ $tr(label) }}</button></div><details v-for="key in faqs" :key="key" class="account-faq"><summary>{{ $tr(t('profile.helpCenterPage.faq.'+key)) }}</summary><p>{{ $tr(t('profile.helpCenterPage.faq.'+key+'Answer')) }}</p></details><p v-if="!faqs.length" class="empty">{{ $tr(t('profile.helpCenterPage.empty',{query})) }}</p></template>
<p v-if="error" class="form-error section-gap" role="alert">{{ $tr(error) }}</p><p v-if="success" class="form-success section-gap" role="status">{{ $tr(success) }}</p></div></template>
